function format(x: string | number) {
	if (typeof x === 'string') return x.toUpperCase();
	return x.toFixed(2);
}

type Shape = { kind: 'circle'; r: number } | { kind: 'square'; a: number };

function area(s: Shape): number {
	switch (s.kind) {
		case 'circle':
			return Math.PI * s.r ** 2;
		case 'square':
			return s.a ** 2;
		default: {
			const unreachable: never = s;
			return unreachable;
		}
	}
}

